<html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ramani Majengo — GIS & 3D Site Studio</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://unpkg.com/maplibre-gl@5.6.1/dist/maplibre-gl.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet">
<style>
:root{--ink:#20251f;--muted:#687066;--paper:#fffdf9;--cream:#f3efe7;--green:#52664d;--line:#ded8cd;--gold:#b68b43}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}h1,h2,h3,h4{font-family:'Playfair Display',serif}.top{min-height:68px;background:var(--paper);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 20px;position:relative;z-index:20}.brand{font-weight:800;letter-spacing:.1em;font-size:.8rem;white-space:nowrap}.brand span{display:inline-grid;place-items:center;width:40px;height:40px;border:1px solid var(--ink);margin-right:9px;font-family:'Playfair Display';font-size:13px}.tools{display:flex;gap:7px;flex-wrap:wrap}.btnx{border:1px solid #cfc8bb;background:#fff;padding:9px 12px;font-weight:700;font-size:12px;color:var(--ink)}.btnx.primary{background:var(--green);color:#fff;border-color:var(--green)}.workspace{height:calc(100vh - 68px);min-height:570px;display:grid;grid-template-columns:280px minmax(0,1fr) 285px}.side{background:var(--paper);overflow:auto;padding:18px;border-right:1px solid var(--line);z-index:5}.right{border-right:0;border-left:1px solid var(--line)}.map{position:relative;min-width:0;min-height:0}.mapbox{position:absolute;inset:0}.section-label{font-size:.67rem;text-transform:uppercase;letter-spacing:.15em;font-weight:800;color:var(--green)}.metric{font-family:'Playfair Display';font-size:26px;font-weight:600}.muted{font-size:12px;color:var(--muted);line-height:1.65}.status{padding:10px 0;font-size:12px;border-bottom:1px solid var(--line)}.coord{font-family:monospace;font-size:11px;word-break:break-all;color:var(--muted);margin-top:10px}.feature{padding:13px 0;border-bottom:1px solid var(--line)}.feature strong{display:block;font-size:13px}.map-hint{position:absolute;left:16px;top:16px;background:rgba(255,253,249,.97);padding:12px 14px;box-shadow:0 10px 35px #0002;z-index:4;max-width:420px;width:min(420px,calc(100% - 32px));border-left:3px solid var(--green)}.search-row{display:flex;gap:6px;margin-top:9px}.search-row input{min-width:0;flex:1;border:1px solid #d6d0c4;background:#fff;padding:10px;font-size:13px;outline-color:var(--green)}.search-row button{border:0;background:var(--green);color:#fff;padding:0 12px;font-weight:700}.suggestions{display:none;max-height:220px;overflow:auto;background:#fff;border:1px solid #ded8cd;border-top:0}.suggestion{display:block;width:100%;text-align:left;background:#fff;border:0;border-bottom:1px solid #eee;padding:9px 10px;font-size:12px}.suggestion:hover{background:#f2f5ef}.mode{font-weight:800;font-size:13px}.canvas2d{width:100%;height:190px;border:1px solid var(--line);background:#faf9f5}.table-mini{width:100%;font-size:11px}.table-mini td{padding:5px 2px;border-bottom:1px solid #eee}.footer-note{font-size:10px;color:#7b8278;margin-top:12px;line-height:1.6}.maplibregl-ctrl-group{border:0!important;box-shadow:0 8px 25px #0002!important}.maplibregl-ctrl-group button{background:#fffdf9!important}.status-good{color:#2f693d}.status-bad{color:#a33}@media(max-width:1050px){.workspace{grid-template-columns:240px minmax(0,1fr)}.right{display:none}}@media(max-width:720px){.top{align-items:flex-start;flex-direction:column;padding:10px 12px}.tools{width:100%}.tools .btnx{flex:1;padding:9px 6px}.workspace{height:calc(100dvh - 118px);min-height:480px;grid-template-columns:1fr}.side{display:none}.map-hint{left:10px;top:10px;width:calc(100% - 20px);max-width:420px}.maplibregl-ctrl-top-right{top:155px!important}}
</style></head><body>
<header class="top"><div class="brand"><span>RM</span>RAMANI MAJENGO</div><div class="tools"><button class="btnx primary" id="drawBtn">Chora kiwanja</button><button class="btnx" id="finishBtn">Maliza</button><button class="btnx" id="houseBtn">Weka nyumba ya 3D</button><button class="btnx" id="view3dBtn">Muonekano wa 3D</button><button class="btnx" id="clearBtn">Futa</button><button class="btnx" id="exportBtn">Pakua GeoJSON</button></div></header>
<div class="workspace"><aside class="side"><div class="section-label mb-2">Taarifa za eneo</div><h4 class="mb-3">Ramani ya kiwanja</h4><div class="metric" id="area">0.00 m²</div><div class="muted">Makadirio ya eneo</div><div class="mt-3 metric" id="perimeter">0.00 m</div><div class="muted">Mzunguko wa kiwanja</div><div class="mt-4 section-label">Pointi za mipaka</div><table class="table-mini mt-2"><tbody id="points"><tr><td class="muted">Bonyeza “Chora kiwanja”, kisha gusa ramani.</td></tr></tbody></table><div class="mt-4 section-label">Zana</div><div class="feature"><strong>Tafuta eneo</strong><span class="muted">Tafuta mtaa, kijiji, jiji au sehemu maarufu kwa jina.</span></div><div class="feature"><strong>GPS ya kifaa</strong><span class="muted">Tumia mahali ulipo kama ruhusa ya location imeruhusiwa.</span></div><div class="feature"><strong>Ramani ya 3D</strong><span class="muted">Geuza ramani kwa tilt na jenga mfano wa 3D wa nyumba kwenye kiwanja.</span></div></aside>
<main class="map"><div id="map" class="mapbox"></div><div class="map-hint"><div class="section-label">Tafuta eneo haraka</div><div class="search-row"><input id="placeSearch" type="search" autocomplete="off" placeholder="Mf. Dodoma, Nkuhungu, UDOM…"><button id="searchBtn">TAFUTA</button><button id="gpsBtn" title="Tumia mahali nilipo">GPS</button></div><div id="suggestions" class="suggestions"></div><div class="mode mt-2" id="modeText">Ramani iko tayari.</div><div class="muted" id="helpText">Tafuta eneo kwa jina au tumia GPS. Chora kiwanja kwa kugusa pointi za mipaka.</div></div></main>
<aside class="side right"><div class="section-label mb-2">Mahali ulipo</div><h4>Data za ramani</h4><div class="status">OpenStreetMap · MapLibre WebGL</div><div class="coord" id="cursor">Sogeza pointer juu ya ramani kuona coordinates.</div><div class="mt-4 section-label">Hali ya 3D</div><div class="status" id="gpuStatus">Inakagua uwezo wa 3D…</div><div class="muted mt-2">Ramani ya msingi inaendelea kufanya kazi hata kama WebGPU haipatikani. Muonekano wa 3D unatumia WebGL.</div><div class="mt-4 section-label">Mchoro wa kiwanja</div><canvas id="plan2d" class="canvas2d mt-2" width="600" height="300"></canvas><div class="muted mt-2">Mfano huu wa nyumba ni wa kuona tu; si mchoro wa ujenzi ulioidhinishwa.</div><div class="mt-4"><a class="btnx primary d-inline-block text-decoration-none" href="index.php">Fungua AI Architecture Studio →</a></div><div class="footer-note">Mipaka, vipimo na miundo inahitaji kuthibitishwa na mpima ardhi na mtaalamu wa majengo kabla ya ujenzi.</div></aside></div>
<script src="https://unpkg.com/maplibre-gl@5.6.1/dist/maplibre-gl.js"></script><script>
const $=id=>document.getElementById(id);
const map=new maplibregl.Map({container:'map',style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm',type:'raster',source:'osm'}]},center:[34.8,-6.16],zoom:6,pitch:0});
map.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');
let drawing=false,points=[],finished=false,house=null,searchMarker=null,searchTimer=null;
const sourceId='plot-source';
function setMessage(title,help){$('modeText').textContent=title;if(help)$('helpText').textContent=help}
function areaPerimeter(){if(points.length<3)return {a:0,p:0};let a=0,p=0;for(let i=0;i<points.length;i++){const j=(i+1)%points.length,[x1,y1]=points[i],[x2,y2]=points[j];const dx=(x2-x1)*111320*Math.cos((y1+y2)*Math.PI/360),dy=(y2-y1)*110540;p+=Math.hypot(dx,dy);a+=x1*y2-x2*y1}a=Math.abs(a)/2*111320*110540*Math.cos(points.reduce((s,x)=>s+x[1],0)/points.length*Math.PI/180);return {a,p}}
function makeFeatures(){const features=[];if(points.length>1)features.push({type:'Feature',properties:{kind:'boundary'},geometry:{type:'LineString',coordinates:points}});if(points.length>=3&&finished)features.push({type:'Feature',properties:{kind:'plot'},geometry:{type:'Polygon',coordinates:[[...points,points[0]]]}});if(house)features.push({type:'Feature',properties:{kind:'house'},geometry:{type:'Polygon',coordinates:[[...house,house[0]]]}});return {type:'FeatureCollection',features}}
function refresh(){const s=map.getSource(sourceId);if(s)s.setData(makeFeatures());points.forEach((p,i)=>{const id='p'+i,data={type:'Feature',properties:{},geometry:{type:'Point',coordinates:p}};if(!map.getSource(id)){map.addSource(id,{type:'geojson',data});map.addLayer({id,type:'circle',source:id,paint:{'circle-radius':5,'circle-color':'#b68b43','circle-stroke-color':'#fff','circle-stroke-width':2}})}else map.getSource(id).setData(data)});const {a,p}=areaPerimeter();$('area').textContent=a.toLocaleString('en-US',{maximumFractionDigits:2})+' m²';$('perimeter').textContent=p.toLocaleString('en-US',{maximumFractionDigits:2})+' m';$('points').innerHTML=points.length?points.map((p,i)=>'<tr><td>P'+(i+1)+'</td><td>'+p[1].toFixed(6)+'</td><td>'+p[0].toFixed(6)+'</td></tr>').join(''):'<tr><td class="muted">Hakuna pointi bado.</td></tr>';draw2d()}
function save(){localStorage.setItem('ramani-majengo-site',JSON.stringify({points,finished,house}))}
function finish(){if(points.length<3){setMessage('Pointi hazitoshi.','Weka angalau pointi tatu kuunda kiwanja.');return}finished=true;drawing=false;setMessage('Kiwanja kimechorwa.','Unaweza kuweka nyumba ya mfano ya 3D au kupakua GeoJSON.');refresh();save()}
function draw2d(){const c=$('plan2d'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#faf9f5';ctx.fillRect(0,0,c.width,c.height);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),pad=35,s=Math.min((c.width-pad*2)/Math.max(maxx-minx,.000001),(c.height-pad*2)/Math.max(maxy-miny,.000001)),xy=p=>[pad+(p[0]-minx)*s,c.height-pad-(p[1]-miny)*s];ctx.beginPath();points.forEach((p,i)=>{const q=xy(p);i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])});if(finished)ctx.closePath();ctx.fillStyle='#e7eee3';ctx.fill();ctx.strokeStyle='#52664d';ctx.lineWidth=3;ctx.stroke();if(house){ctx.beginPath();house.forEach((p,i)=>{const q=xy(p);i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])});ctx.closePath();ctx.fillStyle='#b68b4388';ctx.fill();ctx.strokeStyle='#b68b43';ctx.stroke()}points.forEach((p,i)=>{const q=xy(p);ctx.fillStyle='#b68b43';ctx.beginPath();ctx.arc(q[0],q[1],5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#20251f';ctx.font='11px Arial';ctx.fillText('P'+(i+1),q[0]+7,q[1]-7)})}
map.on('load',()=>{map.addSource(sourceId,{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'plot-fill',type:'fill',source:sourceId,filter:['==',['get','kind'],'plot'],paint:{'fill-color':'#52664d','fill-opacity':.22}});map.addLayer({id:'plot-line',type:'line',source:sourceId,filter:['in',['get','kind'],['literal',['plot','boundary']]],paint:{'line-color':'#52664d','line-width':3}});map.addLayer({id:'house-fill',type:'fill-extrusion',source:sourceId,filter:['==',['get','kind'],'house'],paint:{'fill-extrusion-color':'#b68b43','fill-extrusion-height':9,'fill-extrusion-base':0,'fill-extrusion-opacity':.92}});try{const d=JSON.parse(localStorage.getItem('ramani-majengo-site')||'null');if(d){points=Array.isArray(d.points)?d.points:[];finished=!!d.finished;house=Array.isArray(d.house)?d.house:null;refresh()}}catch(e){}});
map.on('click',e=>{if(!drawing)return;points.push([e.lngLat.lng,e.lngLat.lat]);finished=false;house=null;setMessage('Pointi '+points.length+' imeongezwa.','Endelea kubofya mipaka, kisha bonyeza Maliza.');refresh()});
map.on('dblclick',e=>{if(drawing){e.preventDefault();finish()}});
map.on('mousemove',e=>$('cursor').textContent=e.lngLat.lat.toFixed(6)+', '+e.lngLat.lng.toFixed(6));
function removePoints(){for(let i=0;i<200;i++){if(map.getLayer('p'+i))map.removeLayer('p'+i);if(map.getSource('p'+i))map.removeSource('p'+i)}}
$('drawBtn').onclick=()=>{drawing=true;finished=false;points=[];house=null;removePoints();setMessage('Hali ya kuchora imewashwa.','Gusa ramani kuweka pointi za mipaka ya kiwanja.');refresh()};
$('finishBtn').onclick=finish;
$('clearBtn').onclick=()=>{points=[];house=null;finished=false;drawing=false;localStorage.removeItem('ramani-majengo-site');removePoints();setMessage('Ramani iko tayari.','Tafuta eneo au anza kuchora kiwanja kipya.');refresh()};
$('exportBtn').onclick=()=>{if(points.length<3){setMessage('Chora kiwanja kwanza.');return}const features=[{type:'Feature',properties:{source:'Ramani Majengo',kind:'survey_plot'},geometry:{type:'Polygon',coordinates:[[...points,points[0]]]}}];if(house)features.push({type:'Feature',properties:{source:'Ramani Majengo',kind:'concept_house'},geometry:{type:'Polygon',coordinates:[[...house,house[0]]]}});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({type:'FeatureCollection',features},null,2)],{type:'application/geo+json'}));a.download='ramani-majengo-site.geojson';a.click();URL.revokeObjectURL(a.href)};
$('houseBtn').onclick=()=>{if(!finished||points.length<3){setMessage('Chora na umalize kiwanja kwanza.','Nyumba ya mfano itawekwa ndani ya kiwanja kilichochorwa.');return}const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),cx=(minx+maxx)/2,cy=(miny+maxy)/2,w=(maxx-minx)*.42,d=(maxy-miny)*.42;house=[[cx-w/2,cy-d/2],[cx+w/2,cy-d/2],[cx+w/2,cy+d/2],[cx-w/2,cy+d/2]];map.easeTo({pitch:60,bearing:-25,duration:900});refresh();save();setMessage('Nyumba ya mfano ya 3D imeongezwa.','Huu ni mfano wa dhana tu; tumia AI Architecture Studio kwa mpangilio wa vyumba.')};
$('view3dBtn').onclick=()=>map.easeTo({pitch:map.getPitch()>20?0:60,bearing:map.getPitch()>20?0:-25,duration:800});
async function geocode(q){const url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&addressdetails=1&q='+encodeURIComponent(q+', Tanzania');const res=await fetch(url,{headers:{'Accept':'application/json'}});if(!res.ok)throw new Error('Search service unavailable');return await res.json()}
function showSuggestions(items){const box=$('suggestions');box.innerHTML='';if(!items.length){box.style.display='none';setMessage('Hakuna eneo lililopatikana.','Jaribu jina lingine au ongeza kata/mkoa.');return}items.forEach(item=>{const b=document.createElement('button');b.className='suggestion';b.type='button';b.textContent=item.display_name;b.onclick=()=>goPlace(item);box.appendChild(b)});box.style.display='block'}
function goPlace(item){const lon=+item.lon,lat=+item.lat;$('placeSearch').value=item.name||item.display_name.split(',')[0];$('suggestions').style.display='none';if(searchMarker)searchMarker.remove();searchMarker=new maplibregl.Marker({color:'#b68b43'}).setLngLat([lon,lat]).setPopup(new maplibregl.Popup({offset:25}).setText(item.display_name)).addTo(map);map.flyTo({center:[lon,lat],zoom:Math.max(15,Math.min(18,+item.zoom||16)),pitch:35,speed:1.2});searchMarker.togglePopup();setMessage('Eneo limepatikana.','Ramani imehamia kwenye eneo ulilochagua.');}
async function runSearch(){const q=$('placeSearch').value.trim();if(q.length<2){setMessage('Andika jina la eneo.','Mfano: Dodoma, Nkuhungu, Mlimwa au University of Dodoma.');return}const b=$('searchBtn');b.disabled=true;b.textContent='…';try{showSuggestions(await geocode(q));}catch(e){setMessage('Utafutaji umeshindikana.','Angalia intaneti ujaribu tena; unaweza pia kutumia GPS.')}finally{b.disabled=false;b.textContent='TAFUTA'}}
$('searchBtn').onclick=runSearch;$('placeSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runSearch()}});
$('placeSearch').addEventListener('input',()=>{clearTimeout(searchTimer);const q=$('placeSearch').value.trim();if(q.length<3){$('suggestions').style.display='none';return}searchTimer=setTimeout(async()=>{try{showSuggestions(await geocode(q))}catch(e){}},550)});
$('gpsBtn').onclick=()=>{if(!navigator.geolocation){setMessage('GPS haipatikani kwenye browser hii.');return}$('gpsBtn').disabled=true;$('gpsBtn').textContent='…';navigator.geolocation.getCurrentPosition(pos=>{const p=[pos.coords.longitude,pos.coords.latitude];if(searchMarker)searchMarker.remove();searchMarker=new maplibregl.Marker({color:'#3478b8'}).setLngLat(p).setPopup(new maplibregl.Popup().setText('Mahali ulipo')).addTo(map);map.flyTo({center:p,zoom:17,pitch:40});searchMarker.togglePopup();setMessage('Tumepata mahali ulipo.','GPS imefanya kazi. Unaweza kuanza kuchora eneo hili.');$('gpsBtn').disabled=false;$('gpsBtn').textContent='GPS'},err=>{setMessage('GPS haikufanya kazi.','Ruhusu location kwenye browser na hakikisha unatumia HTTPS.');$('gpsBtn').disabled=false;$('gpsBtn').textContent='GPS'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})};
if('gpu'in navigator)navigator.gpu.requestAdapter().then(a=>$('gpuStatus').textContent=a?'WebGPU ipo; ramani inatumia WebGL kwa uoanifu.':'WebGPU haipo; WebGL inaendelea kufanya kazi.').catch(()=>$('gpuStatus').textContent='WebGL inatumika kwa ramani ya 3D.');else $('gpuStatus').textContent='WebGL inatumika kwa ramani ya 3D.';
</script></body></html>